typedef int nvlMutex;

enum nvlMutexMode
{
  NVL_MUTEX_BLOCK
};

enum
{
  NVL_MAX_STREAM_NUM = 8,
  NVL_STREAM_FLAG_READ_IN_PROGRESS = 1,
  NVL_STREAM_MAX_TRIES = 3600
};

struct nvlStream
{
  int idx;
  unsigned int startSector;
  unsigned int endSector;
  unsigned int readSector;
  unsigned int filesize;
  int bytes_in_last_sect;
  int bufsize;
  char* buf;
  char* endbuf;
  char* pRead;
  char* pWrite;
  char* pLock;
  char* pEndOfData;
  char* pStartOfData;
  int private_buffer;
  int bitrate;
  unsigned int flags;
  int available;
  nvlMutex mtx;
  int lp_skip;
  int requireRewind;
};

struct nvlStreamSystemData_t
{
  char padding[0x7c];
  nvlStream* pStream[NVL_MAX_STREAM_NUM];
};

extern nvlStreamSystemData_t nvlStreamSystemData;
extern int nvlStreamSystemInitialized;
extern void (*nvlStreamFreeFunc)(void*);

int nvlLockMutex(nvlMutex*, nvlMutexMode);
void nvlUnlockMutex(nvlMutex*);
void nvlWaitForVB();
void nvlDestroyMutex(nvlMutex*);
extern "C" void free(void*);
extern "C" void __assert(const char*, int, const char*);

extern const char source_file[];
extern const char initialized_expression[];
extern const char stream_expression[];
extern const char lock_expression[];
extern const char tries_expression[];
extern const char slot_expression[];
extern const char buffer_expression[];

__asm__(".equ nvlStreamSystemData,0x00595E80");
__asm__(".equ nvlStreamSystemInitialized,0x0048AFE0");
__asm__(".equ nvlStreamFreeFunc,0x00596F48");
__asm__(".equ nvlLockMutex__FPi12nvlMutexMode,0x003873E8");
__asm__(".equ nvlUnlockMutex__FPi,0x00387480");
__asm__(".equ nvlWaitForVB__Fv,0x00385650");
__asm__(".equ nvlDestroyMutex__FPi,0x003873A0");
__asm__(".equ free,0x003D0BC8");
__asm__(".equ __assert,0x003CF6B0");
__asm__(".equ source_file,0x0051AD40");
__asm__(".equ initialized_expression,0x0051B338");
__asm__(".equ stream_expression,0x0051B120");
__asm__(".equ lock_expression,0x0051B378");
__asm__(".equ tries_expression,0x0051B300");
__asm__(".equ slot_expression,0x0051B388");
__asm__(".equ buffer_expression,0x0051B3C0");

#define assert_line(condition, line, expression) \
  ((condition) ? (void)0 : __assert(source_file, line, expression))

void nvlStreamDestroy( nvlStream* s )
{
  int   i;

  assert_line( nvlStreamSystemInitialized, 1055, initialized_expression );
  assert_line( s, 1056, stream_expression );

  i = nvlLockMutex( &s->mtx, NVL_MUTEX_BLOCK );
  assert_line( i, 1059, lock_expression );

  for( i = 0; s->flags & NVL_STREAM_FLAG_READ_IN_PROGRESS; i++ )
  {
    assert_line( i < NVL_STREAM_MAX_TRIES, 1063, tries_expression );
    nvlUnlockMutex( &s->mtx );
    nvlWaitForVB();
    nvlLockMutex( &s->mtx, NVL_MUTEX_BLOCK );
  }

  assert_line( nvlStreamSystemData.pStream[s->idx] == s, 1069, slot_expression );
  nvlStreamSystemData.pStream[s->idx] = 0;

  nvlDestroyMutex( &s->mtx );

  if( s->private_buffer )
  {
    assert_line( s->buf, 1083, buffer_expression );
    if( nvlStreamFreeFunc )
    {
      (*nvlStreamFreeFunc)( s->buf );
    }
    else
    {
      free( s->buf );
    }
  }
  if( nvlStreamFreeFunc )
  {
    (*nvlStreamFreeFunc)( s );
  }
  else
  {
    free( s );
  }
}
